## 1. Using Npgsql (Recommended)

### Install Npgsql Package
```bash
dotnet add package Npgsql
```

### Create Database Programmatically
```csharp
using Npgsql;

public class DatabaseCreator
{
    public static void CreateDatabase(string connectionString, string databaseName)
    {
        // Connection string to the default 'postgres' database
        var masterConnectionString = connectionString;

        using (var connection = new NpgsqlConnection(masterConnectionString))
        {
            connection.Open();

            // Check if database exists
            var checkCommand = new NpgsqlCommand(
                $"SELECT 1 FROM pg_database WHERE datname = '{databaseName}'", 
                connection);

            var exists = checkCommand.ExecuteScalar();

            if (exists == null)
            {
                // Create the database
                var createCommand = new NpgsqlCommand(
                    $"CREATE DATABASE \"{databaseName}\"", 
